func quotedSlice(stringSlice []string) string {
	quotedSlice := make([]string, len(stringSlice))

	for i, str := range stringSlice {
		quotedSlice[i] = fmt.Sprintf("\"%s\"", str)
	}

	return strings.Join(quotedSlice, ", ")
}

